export const tunnelTiles=(c,t)=>{const n=Math.sqrt(c.tiles.length),a=c.tiles[t.a],b=c.tiles[t.b],dx=Math.sign(b.x-a.x),dy=Math.sign(b.y-a.y),ids=[];for(let x=a.x,y=a.y;x!==b.x||y!==b.y;x+=dx,y+=dy)ids.push(y*n+x);ids.push(t.b);return ids;};
export function proposeTunnel(c,mode,points){if(!['road','rail','highway'].includes(mode)||points.length<3)return null;const n=Math.sqrt(c.tiles.length);if(points.some(p=>!Number.isInteger(p.x)||!Number.isInteger(p.y)||p.x<0||p.y<0||p.x>=n||p.y>=n))return null;const axis=points.every(p=>p.y===points[0].y)?'x':points.every(p=>p.x===points[0].x)?'y':null;if(!axis)return null;const sorted=[...points].sort((a,b)=>a[axis]-b[axis]);if(sorted.some((p,i)=>i&&p[axis]!==sorted[i-1][axis]+1))return null;const a=c.tiles[sorted[0].y*n+sorted[0].x],b=c.tiles[sorted.at(-1).y*n+sorted.at(-1).x],middle=sorted.slice(1,-1).map(p=>c.tiles[p.y*n+p.x]);if(a.elevation!==b.elevation||middle.some(t=>t.elevation<=a.elevation)||!middle.some(t=>t.elevation>=a.elevation+2))return null;const fail=error=>({ok:false,error,cost:0,points:[]});if(middle.length<6)return fail('A tunnel needs at least six underground tiles between its portals.');if([a,b,...middle].some(t=>t.terrain==='water'||t.radiation))return fail('Tunnel routes need dry, uncontaminated terrain.');if(middle.some(t=>t.subway))return fail('This tunnel would intersect existing subway infrastructure.');for(const t of [a,b])if(t.rubble||t.fire||t.type&&!(mode==='road'&&t.type==='road')||mode!=='rail'&&t.rail||mode!=='highway'&&t.highway)return fail('Tunnel portals need clear land or matching existing approaches.');const ids=sorted.map(p=>p.y*n+p.x);if((c.tunnels||[]).some(t=>tunnelTiles(c,t).some(i=>ids.includes(i))))return fail('Tunnel routes cannot cross or overlap existing tunnels.');const tunnel={mode,a:ids[0],b:ids.at(-1),elevation:a.elevation};return{ok:true,cost:middle.length*({road:100,rail:150,highway:250}[mode])+2*({road:10,rail:20,highway:60}[mode]),points:sorted,tunnel};}
export function installTunnel(c,t){c.tunnels.push(t);for(const i of [t.a,t.b]){const p=c.tiles[i];if(t.mode==='road')p.type='road';else p[t.mode]=true;p.nature=false;}}
export function removeTunnels(c,i,tool){c.tunnels=c.tunnels.filter(t=>!((t.a===i||t.b===i)&&(tool==='bulldoze'||tool==='removeRail'&&t.mode==='rail'||tool==='removeHighway'&&t.mode==='highway')));}
export function tunnelEdges(c,mode){return(c.tunnels||[]).filter(t=>t.mode===mode).map(t=>[t.a,t.b]);}
export function routeLength(c,path){const N=c.tiles.length;let length=path.length?1:0;for(let k=1;k<path.length;k++){const a=c.tiles[path[k-1]%N],b=c.tiles[path[k]%N];length+=Math.max(1,Math.abs(a.x-b.x)+Math.abs(a.y-b.y));}return length;}
export function tunnelStats(c){const counts={road:0,rail:0,highway:0};for(const t of c.tunnels||[])counts[t.mode]+=tunnelTiles(c,t).length-2;return{tunnels:(c.tunnels||[]).length,roadTunnelTiles:counts.road,railTunnelTiles:counts.rail,highwayTunnelTiles:counts.highway};}
export function validateTunnels(c,values){if(!Array.isArray(values)||values.length>c.tiles.length)throw Error('Invalid tunnels.');const used=new Set(),out=[];for(const t of values){if(!t||!['road','rail','highway'].includes(t.mode)||!Number.isInteger(t.a)||!Number.isInteger(t.b)||t.a<0||t.b<=t.a||t.b>=c.tiles.length||!Number.isInteger(t.elevation)||t.elevation<0||t.elevation>8)throw Error('Invalid tunnel.');const a=c.tiles[t.a],b=c.tiles[t.b];if(a.x!==b.x&&a.y!==b.y)throw Error('Tunnel must be straight.');const ids=tunnelTiles(c,t);if(ids.length<8||a.elevation!==t.elevation||b.elevation!==t.elevation||ids.some((i,k)=>used.has(i)||c.tiles[i].terrain!=='land'||k>0&&k<ids.length-1&&(c.tiles[i].elevation<=t.elevation||c.tiles[i].subway))||[a,b].some(p=>t.mode==='road'?p.type!=='road':!p[t.mode]))throw Error('Invalid tunnel route.');for(const i of ids)used.add(i);out.push({mode:t.mode,a:t.a,b:t.b,elevation:t.elevation});}return out;}

export const tunnelAt=(c,i)=>(c.tunnels||[]).find(t=>tunnelTiles(c,t).includes(i));
